CREATE TEMPORARY TABLE tmp_south_america_missing_countries AS
SELECT
  t.country_name,
  COUNT(*) AS rows_waiting
FROM tmp_south_america_airports_import t
LEFT JOIN countries c
  ON c.name = t.country_name
 AND c.world_region_code = 'SOUTH_AMERICA'
WHERE c.id IS NULL
GROUP BY t.country_name
ORDER BY t.country_name;

SELECT * FROM tmp_south_america_missing_countries;

CREATE TEMPORARY TABLE tmp_south_america_preflight_guard (
  guard_value INT NOT NULL
) ENGINE=InnoDB;

INSERT INTO tmp_south_america_preflight_guard (guard_value)
SELECT NULL
FROM tmp_south_america_missing_countries
LIMIT 1;

INSERT INTO icao_prefixes (
  prefix,
  country_id,
  area_name,
  notes
)
SELECT
  x.icao_prefix,
  x.country_id,
  x.country_name,
  'ICAO prefix for South America airport import.'
FROM (
  SELECT
    t.icao_prefix,
    MIN(c.id) AS country_id,
    MIN(t.country_name) AS country_name
  FROM tmp_south_america_airports_import t
  JOIN countries c
    ON c.name = t.country_name
   AND c.world_region_code = 'SOUTH_AMERICA'
  GROUP BY t.icao_prefix
) x
LEFT JOIN icao_prefixes p
  ON p.prefix = x.icao_prefix
WHERE p.prefix IS NULL;

CREATE TEMPORARY TABLE tmp_south_america_missing_prefixes AS
SELECT
  t.icao_prefix,
  COUNT(*) AS rows_waiting
FROM tmp_south_america_airports_import t
LEFT JOIN icao_prefixes p
  ON p.prefix = t.icao_prefix
WHERE p.prefix IS NULL
GROUP BY t.icao_prefix
ORDER BY t.icao_prefix;

SELECT * FROM tmp_south_america_missing_prefixes;

INSERT INTO tmp_south_america_preflight_guard (guard_value)
SELECT NULL
FROM tmp_south_america_missing_prefixes
LIMIT 1;

INSERT INTO airports (
  icao_code,
  country_id,
  icao_prefix,
  iata_code,
  name,
  city,
  location_name,
  subdivision_name,
  latitude,
  longitude,
  elevation_ft,
  airport_type,
  service_category,
  is_civilian,
  is_commercial,
  is_military,
  is_closed,
  operator_country_name,
  aip_url,
  chart_url,
  source_rating_percent,
  data_source_name,
  data_source_url,
  data_quality
)
SELECT
  t.icao_code,
  c.id,
  t.icao_prefix,
  t.iata_code,
  t.name,
  t.city,
  t.location_name,
  t.subdivision_name,
  t.latitude,
  t.longitude,
  t.elevation_ft,
  t.airport_type,
  t.service_category,
  t.is_civilian,
  t.is_commercial,
  t.is_military,
  t.is_closed,
  NULLIF(t.operator_country_name, ''),
  NULL,
  NULL,
  NULL,
  t.data_source_name,
  t.data_source_url,
  t.data_quality
FROM tmp_south_america_airports_import t
JOIN countries c
  ON c.name = t.country_name
 AND c.world_region_code = 'SOUTH_AMERICA'
JOIN icao_prefixes p
  ON p.prefix = t.icao_prefix
ON DUPLICATE KEY UPDATE
  country_id = VALUES(country_id),
  icao_prefix = VALUES(icao_prefix),
  iata_code = VALUES(iata_code),
  name = VALUES(name),
  city = VALUES(city),
  location_name = VALUES(location_name),
  subdivision_name = VALUES(subdivision_name),
  latitude = VALUES(latitude),
  longitude = VALUES(longitude),
  elevation_ft = VALUES(elevation_ft),
  airport_type = VALUES(airport_type),
  service_category = VALUES(service_category),
  is_civilian = VALUES(is_civilian),
  is_commercial = VALUES(is_commercial),
  is_military = VALUES(is_military),
  is_closed = VALUES(is_closed),
  operator_country_name = VALUES(operator_country_name),
  aip_url = VALUES(aip_url),
  chart_url = VALUES(chart_url),
  source_rating_percent = VALUES(source_rating_percent),
  data_source_name = VALUES(data_source_name),
  data_source_url = VALUES(data_source_url),
  data_quality = VALUES(data_quality);

CREATE TABLE IF NOT EXISTS airport_runway_source_notes (
  airport_icao_code CHAR(4) NOT NULL,
  source_note TEXT NOT NULL,
  data_source_name VARCHAR(120) NULL,
  created_at_utc TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (airport_icao_code),

  CONSTRAINT fk_airport_runway_source_notes_airport
    FOREIGN KEY (airport_icao_code)
    REFERENCES airports(icao_code)
    ON UPDATE CASCADE
    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO airport_runway_source_notes (
  airport_icao_code,
  source_note,
  data_source_name
)
SELECT
  t.icao_code,
  TRIM(CONCAT(
    COALESCE(NULLIF(t.runway_note, ''), ''),
    CASE
      WHEN NULLIF(t.runway_note, '') IS NOT NULL AND NULLIF(t.source_row_note, '') IS NOT NULL THEN ' '
      ELSE ''
    END,
    COALESCE(NULLIF(t.source_row_note, ''), '')
  )) AS source_note,
  t.data_source_name
FROM tmp_south_america_airports_import t
JOIN airports a
  ON a.icao_code = t.icao_code
WHERE NULLIF(t.runway_note, '') IS NOT NULL
   OR NULLIF(t.source_row_note, '') IS NOT NULL
ON DUPLICATE KEY UPDATE
  source_note = VALUES(source_note),
  data_source_name = VALUES(data_source_name);

SELECT COUNT(*) AS total_airports
FROM airports;

SELECT
  c.name AS country_name,
  COUNT(*) AS total_airports,
  SUM(CASE WHEN a.latitude IS NOT NULL AND a.longitude IS NOT NULL THEN 1 ELSE 0 END) AS airports_with_coordinates
FROM airports a
JOIN countries c
  ON c.id = a.country_id
WHERE c.world_region_code = 'SOUTH_AMERICA'
GROUP BY c.name
ORDER BY c.name;

COMMIT;
